
const toggleBtn = document.getElementById('theme-toggle');
const html = document.documentElement;

// Set initial theme (saved preference > system preference > light)
const saved = localStorage.getItem('theme');
const systemDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
const initialTheme = saved || (systemDark ? 'dark' : 'light');
html.setAttribute('data-theme', initialTheme);

// Toggle on click
toggleBtn.addEventListener('click', () => {
const current = html.getAttribute('data-theme');
const next = current === 'dark' ? 'light' : 'dark';
html.setAttribute('data-theme', next);
localStorage.setItem('theme', next);
}); 



// Get all posts
let allPostsContainer = document.getElementById("all-posts")

async function getAllPosts() {
    try {
        const response = await fetch('https://jsonplaceholder.typicode.com/posts');
        
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }            
        const posts = await response.json(); 
        allPostsContainer.innerHTML = ""
        posts.forEach(post => {
            const card = document.createElement("div")
            card.innerHTML = `
                <div class="p-2 rounded-lg shadow-sm bg-white">
                    <header class="flex items-center space-x-3 mb-3">
                        <img src="data:image/jpeg;base64," alt="User" class="h-10 w-10 rounded-full" />
                        <div>
                            <p class="font-semibold">${post.userId}</p>
                            <p class="text-xs text-gray-500">2 hrs ago</p>
                        </div>
                    </header>
                        <p class="mb-1 font-bold">${post.title}</p>
                        <p class="mb-3">${post.body}</p>
                        <img src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=600&q=80" alt="Beach" class="rounded max-h-96 w-full object-cover mb-3" />
                        <div class="flex justify-between text-gray-600 text-sm font-semibold">
                        <button class="flex items-center space-x-1 hover:text-blue-600 cursor-pointer">
                            <i class="fas fa-thumbs-up"></i><span>Like</span>
                        </button>
                        <button class="flex items-center space-x-1 hover:text-blue-600 cursor-pointer">
                            <i class="fas fa-comment"></i><span>Comment</span>
                        </button>
                        <button class="flex items-center space-x-1 hover:text-blue-600 cursor-pointer">
                            <i class="fas fa-share"></i><span>Share</span>
                        </button>
                    </div>
                </div>
            `;
            allPostsContainer.appendChild(card);          
        });
    } catch (error) {
        console.error(error.message);
    }
}

getAllPosts();


