// Make post
const createPosts = document.getElementById("new-post");
async function createNewPost() {
    const newPost = {
        title: "Create a new post",
        body: "New post created using POST HTTP method and appended sucessfully",
        userId: 11
    };
    try {
        const response = await fetch('https://jsonplaceholder.typicode.com/posts', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json; charset=UTF-8'
            },
            body: JSON.stringify(newPost)
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const createdPost = await response.json();
        console.log("Successfully created:", createdPost);

        const card = document.createElement("div");
        card.innerHTML = `
         <div class="p-2 rounded-lg shadow-sm bg-white">
            <header class="flex items-center space-x-3 mb-3">
                <img src="data:image/jpeg;base64," alt="User" class="h-10 w-10 rounded-full" />
                <div>
                    <p class="font-semibold">${createdPost.userId}</p>
                    <p class="text-xs text-gray-500">2 hrs ago</p>
                </div>
                </header>
            <span class="bg-green-100 text-green-800 text-xs font-semibold px-2.5 py-0.5 rounded">
                Status: Created (ID: ${createdPost.id})
            </span>
            <h3 class="font-bold text-lg text-gray-900 mb-2">${createdPost.title}</h3>
            <p>${createdPost.body}</p>
            <img src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=600&q=80" alt="Beach" class="rounded max-h-96 w-full object-cover mb-3" />
            <div class="flex justify-between text-gray-600 text-sm font-semibold">
            <button class="flex items-center space-x-1 hover:text-blue-600 cursor-pointer">
                <i class="fas fa-thumbs-up"></i><span>Like</span>
            </button>
            <button class="flex items-center space-x-1 hover:text-blue-600 cursor-pointer">
                <i class="fas fa-comment"></i><span>Comment</span>
            </button>
            <button class="flex items-center space-x-1 hover:text-blue-600 cursor-pointer">
                <i class="fas fa-share"></i><span>Share</span>
            </button>
         </div>
        `;
        
        createPosts.appendChild(card);

    } catch (error) {
        console.error("Failed to create post:", error);
        createPosts.innerHTML = `<p class="text-red-500">Error submitting data.</p>`;
    }
}
createNewPost();

